source='https://senior-secondary.scsa.wa.edu.au/__data/assets/pdf_file/0006/1232466/Applied-Information-Technology-ATAR-Year-11-Syllabus-for-teaching-from-2026.PDF'
bridges={}
def bridge(key,title,chapter,section,models,task,checks,extra=''):
 bridges[key]=dict(title=title,chapter=chapter,section=section,models=models,task=task,checks=checks,extra=extra)
bridge('exports','Optimise a file without losing its purpose','u2-data','match-compression-to-the-purpose',[
 ['Compression purpose','Reduce storage/transfer cost while preserving the information required for use. File bytes, visual detail and playback/rendering support are different checks.'],['Lossy/lossless','A JPEG copy may discard image information; a lossless archive must restore original bytes. Lossless compression does not guarantee a smaller file in every case.'],['Cropping','Removing the opening-hours region reduces content; a smaller image fails the brief if the required hours disappear.'],['Resampling','The supplied 1600 × 1000 image is resampled to 800 × 500: pixel count changes from 1,600,000 to 400,000. That quarter pixel count is not a promise of quarter file bytes.'],['Online/display','The measured JPEG is 28,592 bytes at 800 × 500. Reopen it and judge text/edges at intended display size.'],['Print','A 1600-pixel width placed at 8 inches gives 200 PPI; at 4 inches it gives 400 PPI. Confirm the actual output brief, profile and proof requirements rather than using screen pixels as a print specification.']],
 'Using the supplied master and approved software, produce two delivery copies for a stated screen and print brief. Compare cropping, resampling and compression separately. Reopen each output, measure bytes/dimensions and inspect required information; revise a failing copy.',
 ['Retain the original and editable work.','Label actual settings, measurements, rendering judgement and output conditions.','Explain why byte size alone cannot establish a usable result.'],
 '<p><a href="../production-workflows/formats.html">Measured format outputs and independent export brief</a> · <a href="../publication-workflow/index.html">Print/profile conditions</a></p>')
bridge('versions','Manage cloud copies, versions and real utility evidence','u2-data','keep-versions-and-responsibilities-clear',[
 ['Online management','Use a shared approved location, meaningful names, role-based access and an identified approved copy. Check links and permitted access rather than relying on a filename called final.'],['Version control','A staff member proposes v2; another checks the content and approves it. Retain v1 and a change log. Conflict resolution and rollback need an owner, not merely two renamed copies.'],['Cloud computing','A provider delivers computing/storage services over a network. Collaboration can help remote staff; outages, permissions and sync conflicts still need planning. Sync is not automatically independent backup.'],['Cleanup/cache','Inspect the actual report, identify the specifically approved disposable category and preserve downloads/source files. Clearing cache can remove useful offline copies; a virtual lab is not actual OS operation.'],['Fragmentation','Traditional HDD defragmentation addresses scattered storage locations and mechanical access. Use the OS’s drive-aware guidance for SSDs; do not force HDD treatment onto every drive.'],['Protection categories','Malware is an umbrella; a virus spreads by infecting host material, spyware monitors/collects covertly, and spam is unwanted messaging that may carry malicious content. Anti-malware/anti-virus and spam filtering have different roles and limits.']],
 'Create a v1 document, make a separately saved v2 edit, record the change and approval decision, then restore a disposable copy from an independent backup and compare contents. Complete the linked supervised OS-utility pathway in an approved training environment; if unavailable, mark that skill unverified instead of treating the model as performance.',
 ['Keep versions, approval history and actual restore evidence.','For OS operation record version, drive type, utility, preview/approval, observed action and limits.','Do not run unapproved cleanup, disable protection or use malware samples.'],
 '<p><a href="../production-workflows/recovery.html">Actual disposable ZIP-restore reference and learner task</a> · <a href="../maintenance-lab/guide.html">Supervised utility operation steps</a></p>')
bridge('lan','Justify links, equipment and sharing organisation','u2-networks','draw-the-connections-and-label-their-roles',[
 ['Purpose/advantages/disadvantages','The shop shares a printer and booking files. Sharing reduces duplication but introduces access controls, administration and failure dependencies.'],['Fibre','An optical link carries light and may suit a required distance/capacity; verify interfaces, cost and installation. It is not a reason to replace every short desk cable.'],['Wired/wireless','Cable suits fixed desks; radio supports a roaming laptop but coverage/interference need checking. A stated link rate is not measured application throughput.'],['Rate calculation','For decimal units: 20 MB × 8 / 10 Mb/s = 16 seconds ideally. Protocol overhead, contention and endpoint limits can increase actual time.'],['Physical topology','Wired desks connect to a central switch in a star. An access point adds wireless clients to the LAN; wireless does not by itself specify the sharing model.'],['Client-server/peer-to-peer','A dedicated service can centralise file access; peers can share directly. These describe service organisation, not a replacement for drawing physical links.'],['Component roles','NIC attaches an endpoint; switch links local devices; router connects networks; server supplies a service. A modem suits a modem-based provider link; fibre may use an ONT instead. Combined equipment must still have its roles labelled.']],
 'Draw a LAN for two fixed shop PCs, one roaming laptop and a shared printer. Label media, NIC, switch, access point, router, service equipment and optional server. Compare client-server with peer sharing against the brief, calculate 40 MB at 20 Mb/s, and identify one failure dependency plus a coverage/capacity test.',
 ['Differentiate physical topology from service organisation.','Show the provider boundary and label assumptions needing confirmation.','The independent ideal transfer result is 16 seconds; state units and practical limits.'],
 '<img src="shop-lan.svg" width="900" height="480" alt="Model LAN: provider connection through service equipment and router to a switch, which links a server, wired PCs with NICs, printer and wireless access point; a roaming laptop uses radio.">')
bridge('privacy','Follow personal information from collection to disposal','u2-impacts','collect-for-a-clear-purpose',[
 ['Coverage first','Check whether the organisation/activity is covered by the Privacy Act; small-business exemptions have exceptions. Responsible practice still matters when an exemption applies.'],['Collection','A fictional repair booking needs an item description and approved contact method; a date of birth is not justified merely because a form allows it.'],['Use/access','Using a contact detail for a booking is a different decision from publishing it. Staff require authorised access; a person’s request to access their information requires the applicable identity/scope procedure.'],['Identity theft','Unexpected collection or disclosure can support impersonation. Reduce unnecessary data, restrict access and use an approved verification process rather than exposing a record in a public chat.'],['Disposal','Set a justified retention point, inspect backups/shared copies and use an approved disposal method. Deleting a visible shortcut does not establish that all copies were removed.'],['Digital divide','A device alone does not remove cost, connectivity, skill, language, accessibility or app-availability barriers. Offer an approved alternative and reconcile its bookings with the same record.']],
 'Review a fictional booking specification. Justify each field, describe authorised use, distinguish staff access from an individual access request, identify an impersonation risk and design a retention/disposal record. Evaluate resource, skill and web-app access barriers, with a coordinated fallback.',
 ['Use invented data and record Privacy Act coverage as a checked question.','Avoid assuming no names means anonymous data.','Give a reason and check for each stage of the information lifecycle.'],
 '<p>Primary guidance, checked 27 October 2026: <a href="https://www.oaic.gov.au/privacy/privacy-guidance-for-organisations-and-government-agencies/organisations/small-business">OAIC small-business coverage</a>. Recheck before classroom issue; this is a teaching model, not a legal determination.</p>')
bridge('commerce','Evaluate online retail and communication dependence','u2-impacts','evaluate-online-commerce',[
 ['Improved communication','Online product/service details can reach customers without a shop visit; accuracy, accessible content and response ownership still matter.'],['24/7 communication','A request can arrive outside business hours. Publish the actual response window instead of implying staff are always available.'],['Retail opportunities','Online booking/retail can extend reach but creates payment, fulfilment, support and stock-information dependencies. A broader market is not guaranteed profit.'],['Dependence on electronic/visual communication','An image-only hours notice can exclude a reader; an outage can stop online booking. Provide equivalent text and an approved offline/contact fallback, then reconcile records when service returns.']],
 'Recommend a small online communication/retail improvement for the shop. Explain a benefit, operating cost or dependency, actual staff response expectations and an accessible fallback. Write an outage plan and a check preventing duplicate bookings across channels.',
 ['Separate service availability from staff response time.','Support a productivity claim with workload evidence rather than assuming online is always faster.','Evaluate the user outcome and operational burden together.'])
bridge('media','Build animation and edited audio, then inspect the export','u2-applications','build-a-frame-by-frame-sequence',[
 ['Frame-by-frame','Explicitly set each frame; the supplied 24-frame model has a two-second cycle. Check stored timing, not only an fps label.'],['Tween','Set start/end states and inspect calculated intermediate positions. Tweening reduces manual drawing but still requires motion/timing decisions.'],['Buttons','A Replay control must restart the intended sequence and be reachable by keyboard. A drawn button with no action is not a working control.'],['Audio editing','Keep the source; trim an unwanted portion, adjust level or arrange tracks, then listen to the result. Editing is not a filename change.'],['Converting/exporting','Encode an appropriate delivery format and reopen it on the target player. Retain the editable project separately; exporting a mix can merge editable tracks.']],
 'Use approved animation software or the linked editable starter to create a three-second animation and test replay. Edit a supplied audio clip, save the project, convert/export a delivery copy and inspect playback with a transcript. Integrate the actual media into your shop prototype and record a revision.',
 ['Retain editable animation/audio source and delivered files.','Record actual button behaviour, timing, player/tool version and intelligibility check.','Distinguish creating/editing from analysing the supplied reference.'],
 '<p><a href="../animation-multimedia/animation.html">Editable frame/tween/button lab</a> · <a href="../production-workflows/animation.html">Stored-duration checks</a> · <a href="../production-workflows/multitrack.html">Source tracks and actual export</a></p>')
bridge('web','Author linked, responsive pages with a shared template','u2-applications','separate-structure-from-presentation',[
 ['Links and navigation map','Home links to Services and Contact; each page provides a labelled return route. A map shows destinations and routes, not just three page names.'],['Graphics','Use an appropriate supported format with a useful text alternative; check the actual delivered path and dimensions.'],['Templates','A repeated header, navigation and footer form a shared layout pattern. Edit consistent elements across pages without forcing identical content.'],['HTML/HTM and CSS','HTML marks up structure and links; .html/.htm are alternative extensions. CSS controls presentation, including layout and spacing. The filename alone does not validate either.'],['Online collaboration','A shared document supports co-editing/comments; asynchronous review leaves a record; a call can resolve questions quickly. Assign editor/reviewer roles and retain approval/version decisions.'],['Responsive design','The reference stacks cards at a narrow breakpoint rather than shrinking all text. Test narrow/wide, text enlargement, link routes and keyboard focus in the delivered files.']],
 'Copy the three-page reference into your working folder. Draw its navigation map, change fictional hours and a long service title, add your edited media/graphic with text alternatives and explain the HTML/CSS roles. Use an approved shared review process, record who changes/approves content, and test every route, narrow/wide layout and keyboard operation.',
 ['Retain the HTML, shared CSS, assets, navigation map and version/review record.','Reopen the delivery folder and check relative links after moving it.','An attractive screenshot is not evidence of working navigation.'],
 '<p><a href="shop/home.html">Open the finished three-page reference</a> · <a href="shop/site.css" download>Inspect the shared CSS</a> · <a href="navigation-map.svg" download>Navigation-map model</a> · <a href="../web-standards/index.html">Independent editable web starter</a></p>')
bridge('project','Manage requirements, dependencies and a tested handover','u2-projects','put-tasks-in-a-useful-order',[
 ['Client requirements','The fictional shop needs visitors to find services, opening hours and contact guidance. Record three testable criteria and confirm missing details.'],['Plan of action','Approve facts → draft page/media → review → integrate → test → revise → deliver. Each task has an owner and a concrete output.'],['Time/dependencies','A one-lesson edit depends on approved wording; integration depends on usable media exports. If approval slips, re-sequence independent layout work and record the scope/time decision.'],['Resources','Check available tools, source rights, staff time, devices and browser/player support. Two tasks cannot run in parallel if they require the same unavailable person or equipment.'],['Evaluation','Observe the required task, compare against each criterion, record a specific revision and retest. Keep failed/untested separate from passed.'],['Design process and compliance with brief','Use the chosen process to create an actual prototype. Handover includes source files, delivery files, test record, known limits and ownership of maintenance. A plan alone does not prove the delivered result meets requirements.']],
 'Use your small shop prototype as one existing project. Produce a requirements/check table, action plan with owners/durations/dependencies/resources and checkpoints. Build incrementally, run client-task tests, revise a meaningful issue and repeat its check. Evaluate every requirement and record a handover with remaining limitations.',
 ['Link requirements to actual outputs and observations.','Explain time/scope changes and resource conflicts.','Keep planning, production and evaluation records together.'])

rows=[]
def add(area,kind,page,n,label,key,section,children=()):
 root=f'{kind[0]}{n}';base=f'U2-{area.upper()}-{root}';b=bridges[key]
 def item(id,path,label,parent='',context=False):
  rows.append(dict(id=id,area=area,kind=kind,page=page,locator=f'{area} / {kind} / {path}',summary=label,parent=parent,context=context,explanation=f'../../index.html#topic/{b["chapter"]}/{section}',worked=f'{key}.html#worked',practice=f'{key}.html#independent',evidence=f'{key}.html#checks',status='Parent context: review child rows' if context else 'Authored task/model located; performance unverified' if kind=='Skills' else 'Authored explanation/model/task located; review pending',limitation='Independent subject review pending.'+(' Actual learner output and observations remain unverified.' if kind=='Skills' else '')))
 item(base,root,label,context=bool(children))
 for i,child in enumerate(children,1):
  if isinstance(child,tuple):
   name,leaves=child;pid=f'{base}.{i}';item(pid,f'{root}.{i}',name,base,True)
   for j,leaf in enumerate(leaves,1):item(f'{pid}.{j}',f'{root}.{i}.{j}',leaf,pid)
  else:item(f'{base}.{i}',f'{root}.{i}',child,base)

