content={'home':('Fictional bicycle shop','<p>Find services, hours and contact guidance. This is a classroom prototype, not a real business.</p><div class="cards"><section><h2>Repair services</h2><p>Ask about a safety check or small repair.</p><a href="services.html">See repair services</a></section><section><h2>Opening hours</h2><p>Monday–Friday, 9 am–5 pm.</p><a href="contact.html">How to enquire</a></section></div>'), 'services':('Services','<h2>Safety check</h2><p>Describe the issue before agreeing a repair scope.</p><h2>Small repair</h2><p>The fictional client confirms required parts and time before a booking.</p><p><a href="contact.html">Read contact and response guidance</a></p>'), 'contact':('Contact guidance','<p>No contact details or personal information are collected here.</p><p>For this fictional exercise, ask through your teacher’s approved channel. Ordinary response window: Monday–Friday, 9 am–5 pm. A web page being available after hours does not mean instant staff support.</p><p>If a customer cannot use the online route, agree an accessible alternative and reconcile it with the same booking record.</p>')}
for key,(title,body) in content.items():
 nav=''.join(f'<a href="{name}.html"'+(' aria-current="page"' if key==name else '')+'>'+name.title()+'</a>' for name in content)
 (shop/f'{key}.html').write_text(f'<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · AIT prototype</title><link rel="stylesheet" href="site.css"></head><body><header><p>AIT · FICTIONAL REFERENCE PROTOTYPE</p><nav aria-label="Shop pages">{nav}</nav></header><main><h1>{title}</h1>{body}</main><footer><a href="../web.html">Return to the worked authoring task</a></footer></body></html>',encoding='utf-8')
